<?php require 'includes/functions.php';$p=query(product_sql().' WHERE p.id=? AND p.is_active=1',[number('id',true)])->fetch();if(!$p){http_response_code(404);$pageTitle='Product not found';require 'includes/header.php';echo '<div class="container section"><h1>Product not found</h1><a href="'.e(url('new-arrivals.php')).'">Browse the collection</a></div>';require 'includes/footer.php';exit;}$images=query('SELECT * FROM product_images WHERE product_id=? ORDER BY sort_order,id',[$p['id']])->fetchAll();$pageTitle=$p['brand'].' '.$p['name'];require 'includes/header.php';?>
<section class="container section"><div class="breadcrumb"><a href="<?=e(url('new-arrivals.php'))?>">Collection</a> / <?=e($p['brand'])?> / <?=e($p['name'])?></div><div class="detail-grid"><div class="gallery"><div class="main-photo"><img id="main-photo" src="<?=e(url($images[0]['path']??'images/placeholder.svg'))?>" alt="<?=e($pageTitle)?>"></div><div class="thumbnails"><?php foreach($images as $i=>$im):?><a href="<?=e(url($im['path']))?>" data-gallery="<?=e(url($im['path']))?>" aria-label="View <?=e($pageTitle)?> photo <?=$i+1?>"><img src="<?=e(url($im['path']))?>" alt="<?=e($pageTitle)?> photo <?=$i+1?>"></a><?php endforeach;?></div></div><div class="product-info"><span class="eyebrow"><?=e($p['brand'])?></span><h1><?=e($p['name'])?></h1><p class="muted"><?=e($p['concentration'].' · '.$p['size_ml'].' ml · '.$p['category'])?></p><div class="price large"><?=money($p['price'])?></div><p class="availability <?=available($p)?'':'out'?>"><?=available($p)?'In stock — ready for your collection':'SOLD OUT'?></p><p class="description"><?=nl2br(e($p['description']))?></p><form class="purchase" action="<?=e(url('cart.php'))?>" method="post"><?php csrf();?><input type="hidden" name="action" value="add"><input type="hidden" name="product_id" value="<?=$p['id']?>"><label>Quantity<input name="quantity" type="number" min="1" max="<?=max(1,min(99,$p['stock']))?>" value="1" required <?=available($p)?'':'disabled'?>></label><button <?=available($p)?'':'disabled'?>><?=available($p)?'Add to Cart':'Sold Out'?></button></form><p class="muted small">Cash on delivery · Free delivery on orders from USD 50</p><div class="notes"><?php foreach(['top_notes'=>'Top notes','heart_notes'=>'Heart notes','base_notes'=>'Base notes'] as $key=>$label):?><div><span class="eyebrow"><?=$label?></span><p><?=e($p[$key])?></p></div><?php endforeach;?></div></div></div></section><section class="container section"><span class="eyebrow">EXPLORE THE HOUSE</span><h2>More from <?=e($p['brand'])?></h2><div class="product-grid"><?php $related=query(product_sql().' WHERE p.brand_id=? AND p.id<>? AND p.is_active=1 LIMIT 4',[$p['brand_id'],$p['id']])->fetchAll();foreach($related as $r)product_card($r);if(!$related)echo '<p class="muted">More fragrances from this house are coming soon.</p>';?></div></section><?php require 'includes/footer.php';?>
